import{_ as o,l as i,o as e,c as s,v as t,p as A,x as l,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"导向自组装 DSA","description":"","frontmatter":{"title":"导向自组装 DSA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dsa-dpt.md","filePath":"litho/dsa-dpt.md","lastUpdated":1789023840000}'),n={name:"litho/dsa-dpt.md"};function h(D,a,B,c,_,m){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="导向自组装-dsa" tabindex="-1">导向自组装 DSA <a class="header-anchor" href="#导向自组装-dsa" aria-label="Permalink to &quot;导向自组装 DSA&quot;">​</a></h1><div class="epigraph"><p>嵌段共聚物自己会选一个热力学节距；光刻只负责把导向图画对。DSA 是补投影光刻的节距，不是再买一台更短波长的镜头。</p><footer>—— 对照 C. T. Black 对半导体微电子中聚合物自组装的论述，以及 IMEC 等公开的 DSA 集成</footer></div><p><a href="/litho/ald-ale">上一课</a>把厚度收成自限制循环，对象是膜，不是节距。缺口是：节距仍由 EUV 或多重曝光定，薄膜循环填不进更密的线。导向自组装（DSA）用嵌段共聚物的本征周期做一次化学的节距倍增或孔收缩，光刻只做导向（化学外延或图形外延）。对照纳米压印从下一课才开始；本课不把模板接触当成自组装。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多重曝光用多次套刻换节距，<a href="/litho/sadp-saqp">SADP</a> 用侧墙换节距。两者都把「谁决定半节距」交给沉积或套刻。嵌段共聚物（典型 PS-<em>b</em>-PMMA 一类）在退火后相分离，周期 \\(L_0\\) 由链长和相互作用参数钉住，不是由 \\(\\lambda/\\mathrm{NA}\\) 钉住。问题是：如何让这张热力学格子对准器件需要的位置和缺陷密度。</p><p>没有导向，晶粒随机，缺陷不可用。导向过疏，缺陷湮灭不完；导向过密，又把光刻难度买回来，DSA 没有省下层。Black 把这条路写成微电子里的聚合物自组装：有用的是<strong>导向之后的</strong>周期，不是实验室里漂亮的指纹织构。</p><h3 id="dsa-不是胶" tabindex="-1">DSA 不是胶 <a class="header-anchor" href="#dsa-不是胶" aria-label="Permalink to &quot;DSA 不是胶&quot;">​</a></h3><p>抗蚀剂记录空中像；DSA 膜在已有导向上相分离，再选择性去掉一相。它不替代 CAR 的 \\(\\gamma\\)，也不替代 EUV 随机统计的全部——导向图本身仍要光刻。把 DSA 写成「不用镜头的光刻」，会漏掉导向层的套刻、CD 和缺陷。</p><p><span class="marginnote">\\(L_0\\) 随分子量调，不是连续旋钮到任意设计节距。设计必须落在共聚物能锁住的离散周期附近。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条公开路线。化学外延（chemoepitaxy）：先用光刻做出浸润性条带（如 LiNe 一类流程在 IMEC / 大学合作中公开），共聚物在化学对比上注册，线密度可以是导向的倍数。图形外延（graphoepitaxy）：光刻先挖槽或孔，共聚物在侧壁约束下填入，常用于孔收缩或槽内线。随后等离子选择去掉一相，留下的一相当硬掩模往下转。</p><p>缺陷（位错、桥、漏导向）是良率项。退火时间、膜厚相对于 \\(L_0\\)、导向 CD 误差，都会改缺陷密度。IMEC 公开集成强调与逻辑或存储的设计规则对齐，而不是只报一段 TEM。本课不把 DSA 写成已经替换 EUV 量产关键层；公开状态是互补与试点，按层评估。</p>',12)),(e(),A(d,null,{default:l(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIT%5B%22%E5%85%89%E5%88%BB%E5%AF%BC%E5%90%91%E5%9B%BE%22%5D%20--%3E%20CHE%5B%22%E5%8C%96%E5%AD%A6%E5%A4%96%E5%BB%B6%22%5D%0A%20%20LIT%20--%3E%20GRA%5B%22%E5%9B%BE%E5%BD%A2%E5%A4%96%E5%BB%B6%22%5D%0A%20%20BCP%5B%22%E5%B5%8C%E6%AE%B5%E5%85%B1%E8%81%9A%E7%89%A9%20L0%22%5D%20--%3E%20ANN%5B%22%E9%80%80%E7%81%AB%E7%9B%B8%E5%88%86%E7%A6%BB%22%5D%0A%20%20CHE%20--%3E%20ANN%0A%20%20GRA%20--%3E%20ANN%0A%20%20ANN%20--%3E%20ET%5B%22%E9%80%89%E6%8B%A9%E5%8E%BB%E9%99%A4%E4%B8%80%E7%9B%B8%22%5D%0A%20%20ET%20--%3E%20HM%5B%22%E7%A1%AC%E6%8E%A9%E6%A8%A1%E8%8A%82%E8%B7%9D%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与-sadp、euv-的分工" tabindex="-1">与 SADP、EUV 的分工 <a class="header-anchor" href="#与-sadp、euv-的分工" aria-label="Permalink to &quot;与 SADP、EUV 的分工&quot;">​</a></h3><p>SADP 的半节距来自薄膜厚度，套刻主要在切线层。DSA 的半节距来自 \\(L_0\\)，导向层的 CD 和套刻决定注册误差。EUV 单次仍可能做导向，因为导向可以比最终节距松。三条路付的账不同：套刻、沉积均匀性、还是缺陷退火。DTCO 要选的是哪一种缺陷可被设计规则吸收。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Flory–Huggins 相互作用驱使两嵌段分离；在薄膜约束下形成直立层状或圆柱。导向提供化学势或几何边界，把晶粒取向锁到晶圆网格上。倍频来自「一个导向周期里塞进 \\(n\\) 个 \\(L_0\\)」。失败模式是注册滑移和粒界：热力学最低能量仍可能卡在亚稳缺陷，需要足够的退火与合适的导向强度。</p><p>这与 ALD 的自限制不同：ALD 按循环加厚度；DSA 按链长选节距。都是「把控制权交给材料本征尺度」，但一个管膜厚，一个管横向周期。</p><p><span class="marginnote">PMMA 去除后的选择比和 LER 决定能不能当硬掩模。漂亮的相分离图不等于可转印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明某国产 DSA 产线的 wph 或缺陷密度。不要把 IBM / IMEC 公开演示写成所有逻辑层已切换。溶剂退火、高 χ 新材料可以改 \\(L_0\\) 和缺陷，仍要过导向与转印两关。DSA 不抬 NA，不取消套刻；导向层仍要对准前层。</p><p>下一课的纳米压印是另一条「非投影」路：物理接触复印，不是热力学格子。</p><p><span class="marginnote">出处：C. T. Black 等对聚合物自组装进入微电子的综述；IMEC 等 DSA chemo/grapho 公开集成。不编造未公开的量产缺陷表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DSA 用嵌段共聚物的 \\(L_0\\) 补节距，光刻做导向。</li><li>化学外延与图形外延是两条集成，不是一种胶。</li><li>缺陷与注册误差是良率，不只看相分离 TEM。</li><li>与 SADP、EUV 分工不同，不能互相替代宣传。</li><li>纳米压印下一课对照。</li><li>出处：Black；IMEC DSA 公开材料。</li></ul>',12))])}const C=o(n,[["render",h]]);export{u as __pageData,C as default};
